use App\Models\Set\AvatarSet as AvatarSet;

// Do not edit this file, rerun gen.php to update!
class Message extends genClass
{
    protected static string $use_table = "message";
    // get and set
    public ?int $_AvatarLink {
        get => $this->getField(fieldName: "avatarLink");
        set {
            $this->updateField(fieldName: "avatarLink", value: $value);
        }
    }
    public ?string $_Message {
        get => $this->getField(fieldName: "message");
        set {
            $this->updateField(fieldName: "message", value: $value);
        }
    }
    // Data Design
    protected $fields = [
        "id",
        "avatarLink",
        "message",
    ];
    protected $dataset = [
        "id" => ["type" => "int", "value" => null],
        "avatarLink" => ["type" => "int", "value" => null],
        "message" => ["type" => "str", "value" => null],
    ];
    // Setters
    /**
    * setAvatarLink
    */
    protected function setAvatarLink(?int $newValue): void
    {
        $this->updateField("avatarLink", $newValue);
    }
    /**
    * setMessage
    */
    protected function setMessage(?string $newValue): void
    {
        $this->updateField("message", $newValue);
    }
    // Getters
    protected function getAvatarLink(): ?int
    {
        return $this->getField("avatarLink");
    }
    protected function getMessage(): ?string
    {
        return $this->getField("message");
    }
    // Loaders
    public function loadByAvatarLink(int $avatarLink, ?array $limitFields = null): SingleLoadReply
    {
        return $this->loadByField(
            "avatarLink",
            $avatarLink
        , limitFields: $limitFields);
    }
    public function loadByMessage(string $message, ?array $limitFields = null): SingleLoadReply
    {
        return $this->loadByField(
            "message",
            $message
        , limitFields: $limitFields);
    }
    public function relatedAvatar(?array $limitFields = null): AvatarSet
    {
        $ids = [$this->getAvatarLink()];
        $collection = new AvatarSet();
        if ($limitFields !== null) {
            $collection->limitFields($limitFields);
        }
        $collection->loadFromIds($ids);
        return $collection;
    }
}
